 "content": "def transform(grid):
    """Decode a separator band across a regular array of repeated motifs."""
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    # The solid 3-band marks one complete row or column of motif slots.
    row_bands = [r for r, row in enumerate(g) if all(v == 3 for v in row)]
    col_bands = [c for c in range(w) if all(g[r][c] == 3 for r in range(h))]
    bands = []
    for coords, axis in ((row_bands, 0), (col_bands, 1)):
        if coords:
            groups = []
            start = prev = coords[0]
            for x in coords[1:]:
                if x != prev + 1:
                    groups.append(list(range(start, prev + 1)))
                    start = x
                prev = x
            groups.append(list(range(start, prev + 1)))
            bands.extend((len(group), axis, group[0]) for group in groups)
    if not bands:
        return g
    size, axis, band_start = max(bands)
    stride = size + 1
    n = (h + 1) // stride if axis == 0 else (w + 1) // stride

    # Recover the shared motif from an existing non-separator slot.
    motif = None
    for tr in range(n):
        for tc in range(n):
            r0, c0 = tr * stride, tc * stride
            tile = [row[c0:c0 + size] for row in g[r0:r0 + size]]
            if any(v == 2 for row in tile for v in row) and not any(v == 3 for row in tile for v in row):
                motif = [[1 if v == 2 else 0 for v in row] for row in tile]
                break
        if motif is not None:
            break
    if motif is None:
        return [[0 if v == 3 else v for v in row] for row in g]

    # Remove the separator. Reconstruct only those hidden motifs whose
    # position-indexed marker cell is present in the shared motif, and mark
    # that cell in every visible or reconstructed instance.
    out = [[0 if v == 3 else v for v in row] for row in g]
    for tr in range(n):
        for tc in range(n):
            mr, mc = tr, tc
            if mr >= size or mc >= size or motif[mr][mc] == 0:
                continue
            r0, c0 = tr * stride, tc * stride
            tile = [row[c0:c0 + size] for row in g[r0:r0 + size]]
            is_separator_tile = all(v == 3 for row in tile for v in row)
            if is_separator_tile:
                for i in range(size):
                    for j in range(size):
                        if motif[i][j]:
                            out[r0 + i][c0 + j] = 2
            if out[r0 + mr][c0 + mc] == 2:
                out[r0 + mr][c0 + mc] = 8
    return out

